6	export function compileSessionPattern(pattern: string): RegExp {
7	  const escaped = pattern
8	    .replace(/[.+^${}()|[\]\\]/g, "\\$&")
9	    .replace(/\*\*/g, "\u0000")
10	    .replace(/\*/g, "[^:]*")
11	    .replace(/\u0000/g, ".*");
12	  return new RegExp(`^${escaped}$`);
13	}
14	
15	/** Compile all configured ignore patterns once at startup. */
16	export function compileSessionPatterns(patterns: string[]): RegExp[] {
17	  return patterns.map((pattern) => compileSessionPattern(pattern));
18	}
19	
20	/** Check whether a session key matches any compiled ignore pattern. */
21	export function matchesSessionPattern(sessionKey: string, patterns: RegExp[]): boolean {
22	  return patterns.some((pattern) => pattern.test(sessionKey));
