66	  protected String customFormatMessage(final LogRecord iRecord) {
67	    final Level level = iRecord.getLevel();
68	    final String message = AnsiCode.format(iRecord.getMessage(), false);
69	    final Object[] additionalArgs = iRecord.getParameters();
70	    final String requester = getSourceClassSimpleName(iRecord.getLoggerName());
71	
72	    final StringBuilder buffer = new StringBuilder(512);
73	    buffer.append(EOL);
74	    synchronized (dateFormat) {
75	      buffer.append(dateFormat.format(new Date()));
76	    }
77	
78	    buffer.append(" %-5.5s ".formatted(level.getName()));
79	
80	    if (requester != null) {
81	      buffer.append("[");
82	      buffer.append(requester);
83	      buffer.append("] ");
84	    }
85	
86	    // FORMAT THE MESSAGE
87	    try {
88	      if (additionalArgs != null)
89	        buffer.append(message.formatted(additionalArgs));
90	      else
91	        buffer.append(message);
92	    } catch (final IllegalFormatException ignore) {
93	      buffer.append(message);
94	    }
95	
96	    return AnsiCode.format(buffer.toString(), false);
97	  }
