145	// GetPendingBackupNames returns the pending backup list
146	func (list BackupList) GetPendingBackupNames() []string {
147		// Retry the backup if another backup is running
148		pendingBackups := make([]string, 0, len(list.Items))
149		for _, concurrentBackup := range list.Items {
150			if concurrentBackup.Status.IsDone() {
151				continue
152			}
153			if !concurrentBackup.Status.IsInProgress() {
154				pendingBackups = append(pendingBackups, concurrentBackup.Name)
155			}
156		}
157	
158		return pendingBackups
159	}
