161	// CanExecuteBackup control if we can start a reconciliation loop for a certain backup.
162	//
163	// A reconciliation loop can start if:
164	// - there's no backup running, and if the first of the sorted list of backups
165	// - the current backup is running and is the first running backup of the list
166	//
167	// As a side effect, this function will sort the backup list
168	func (list *BackupList) CanExecuteBackup(backupName string) bool {
169		var foundRunningBackup bool
170	
171		list.SortByName()
172	
173		for _, concurrentBackup := range list.Items {
174			if concurrentBackup.Status.IsInProgress() {
175				if backupName == concurrentBackup.Name && !foundRunningBackup {
176					return true
177				}
178	
179				foundRunningBackup = true
180				if backupName != concurrentBackup.Name {
181					return false
182				}
183			}
184		}
185	
186		pendingBackups := list.GetPendingBackupNames()
187		if len(pendingBackups) > 0 && pendingBackups[0] != backupName {
188			return false
189		}
190	
191		return true
192	}
