291	fn is_instance_method(ty: &syntax::types::Type, type_id: &str) -> bool {
292	    let func_ty = match ty {
293	        syntax::types::Type::Forall { body, .. } => body,
294	        other => other,
295	    };
296	    match func_ty {
297	        syntax::types::Type::Function { params, .. } if !params.is_empty() => {
298	            type_name(&params[0]).is_some_and(|name| name == type_id)
299	        }
300	        _ => false,
301	    }
302	}
